import type { ErrorObject } from "ajv"

/** Ajv ValidateFunction 类型 */
export interface ValidateFunction {
  (data: unknown): boolean
  errors?: ErrorObject[] | null
}

/** Schema 位置到 validator 函数的映射 */
const validatorMap: Record<string, ValidateFunction> = {
  'common.schema.json#/$defs/UUID': validateUUID,
  'common.schema.json#/$defs/ServerVersion': validateServerVersion,
  'common.schema.json#/$defs/Rfc3339DateTime': validateRfc3339DateTime,
  'common.schema.json#/$defs/MondayDate': validateMondayDate,
  'recipe.schema.json#/$defs/RecipeView': validateRecipeView,
  'recipe.schema.json#/$defs/RecipeDraft': validateRecipeDraft,
  'recipe.schema.json#/$defs/RecipePatchRequest': validateRecipePatchRequest,
  'plan.schema.json#/$defs/WeeklyPlanView': validateWeeklyPlanView,
  'recipe.schema.json#/$defs/AddRecipeInput': validateAddRecipeInput,
  'recipe.schema.json#/$defs/UpdateRecipeInput': validateUpdateRecipeInput,
  'recipe.schema.json#/$defs/DeleteRecipeInput': validateDeleteRecipeInput,
  'recipe.schema.json#/$defs/RestoreRecipeInput': validateRestoreRecipeInput,
  'recipe.schema.json#/$defs/SearchRecipesInput': validateSearchRecipesInput,
  'recipe.schema.json#/$defs/BatchGenerateRecipesInput': validateBatchGenerateRecipesInput,
  'plan.schema.json#/$defs/GenerateWeeklyPlanInput': validateGenerateWeeklyPlanInput,
  'plan.schema.json#/$defs/UpdatePlanItemInput': validateUpdatePlanItemInput,
}

/**
 * 获取预编译的 validator
 */
export function getValidator(file: string, defPath: string): ValidateFunction {
  const key = `${file}#${defPath}`
  const validator = validatorMap[key]
  if (!validator) throw new Error(`No validator for: ${key}`)
  return validator
}

